<?php $v=$form?:[]; $edit=!empty($form);?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><?php if($edit):?><input type="hidden" name="id" value="<?=e($v['id'])?>"><?php endif;?><div class="grid"><p><label>Account</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=e($a['id'])?>" <?=isset($v['account_id'])&&(int)$v['account_id']===(int)$a['id']?'selected':''?>><?=e($a['name'])?> (<?=e($a['currency'])?>)</option><?php endforeach;?></select></p><p><label>Ticket</label><input name="ticket" value="<?=e($v['ticket']??'')?>"></p><p><label>Symbol</label><input name="symbol" value="<?=e($v['symbol']??'')?>" required></p><p><label>Side</label><select name="side"><option value="long" <?=($v['side']??'long')==='long'?'selected':''?>>Long</option><option value="short" <?=($v['side']??'')==='short'?'selected':''?>>Short</option></select></p><p><label>Status</label><select name="status"><option value="closed" <?=($v['status']??'closed')==='closed'?'selected':''?>>Closed</option><option value="open" <?=($v['status']??'')==='open'?'selected':''?>>Open</option></select></p><p><label>Opening time</label><input type="datetime-local" name="opened_at" value="<?=isset($v['opened_at'])?e(date('Y-m-d\\TH:i',strtotime($v['opened_at']))):''?>" required></p><p><label>Closing time</label><input type="datetime-local" name="closed_at" value="<?=!empty($v['closed_at'])?e(date('Y-m-d\\TH:i',strtotime($v['closed_at']))):''?>"></p><p><label>Quantity</label><input type="number" step=".00000001" min=".00000001" name="quantity" value="<?=e($v['quantity']??'')?>" required></p><p><label>Entry price</label><input type="number" step=".0000000001" min="0" name="entry_price" value="<?=e($v['entry_price']??'')?>" required></p><p><label>Stop loss</label><input type="number" step=".0000000001" min="0" name="stop_loss" value="<?=e($v['stop_loss']??'')?>"></p><p><label>Take profit</label><input type="number" step=".0000000001" min="0" name="take_profit" value="<?=e($v['take_profit']??'')?>"></p><p><label>Exit price</label><input type="number" step=".0000000001" min="0" name="exit_price" value="<?=e($v['exit_price']??'')?>"></p><p><label>Fees</label><input type="number" step=".00000001" min="0" name="fees" value="<?=e($v['fees']??'0')?>"></p></div><p><label>Notes</label><textarea name="notes"><?=e($v['notes']??'')?></textarea></p><button><?=$edit?'Save changes':'Add trade'?></button><?php if($edit):?> <a href="/trades">Cancel</a><?php endif;?></form>
